require "rails_helper"
require_relative "../../../../spec/support/timekeeping/contract"

RSpec.describe "Reservation request helper: route names from the contract" do
  include_context "timekeeping entry writes"

  # "Any wire or credential change means editing every copy." The route list
  # must come from contracts/timekeeping/reservations.yml, and a misspelt route
  # must fail loudly instead of posting to a blank path that answers 404 and
  # passes a refusal check by accident.
  it "lists exactly the contract's reservation routes and refuses to post a route the contract does not name" do
    company = timekeeping_arrange.company
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)

    expect(reservation_routes).to eq(TimekeepingContract.load(:reservations).fetch("routes").keys)
    expect(reservation_routes).to eq(%w[prepare commit abort mark_billed detach_entries])
    before = reservation_row_counts

    expect { reservation_post("refund", company:, credential: service, body: { "operation_id" => SecureRandom.uuid }) }
      .to raise_error(StandardError)
    expect(reservation_row_counts).to eq(before)
  end
end

require "rails_helper"

RSpec.describe "Reservation request helper: conflicted prepare retried" do
  include_context "timekeeping entry writes"

  # A refused prepare that left its operation row behind would turn the retry
  # into a replay or an unresolved_operation refusal.
  it "retries a conflicted prepare under the same operation id through reservation_post and gets a first-attempt answer" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    free = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    held = timekeeping_arrange.reserved_entry(company:, invoice_id: 777, state: "committed")
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    operation_id = SecureRandom.uuid
    body = { "invoice_id" => 501, "operation_id" => operation_id, "disposition" => "active" }
    before = reservation_row_counts

    refused = reservation_post("prepare", company:, credential: service, body: body.merge("entries" => [free, held]))

    expect([refused.status, refused.parsed_body]).to eq(
      [409, { "reason" => "conflict", "conflicts" => [{ "entry_id" => held, "reason" => "on_another_invoice" }] }]
    )
    expect(reservation_row_counts).to eq(before)

    retried = reservation_post("prepare", company:, credential: service, body: body.merge("entries" => [free]))

    expect([retried.status, retried.parsed_body]).to eq(
      [200, { "operation_id" => operation_id, "state" => "prepared", "entries" => [{ "entry_id" => free, "company_id" => company }] }]
    )
    expect(Reservation.where(entry_id: held).pluck(:invoice_id, :state)).to eq([[777, "committed"]])
  end
end

require "rails_helper"

RSpec.describe "Reservation request helper: outbox failure part-way through prepare" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # "Every reservation change that flips `locked`, every mark-billed and every detach writes an audit row and an outbox snapshot row in the same transaction as the change."
  it "leaves every reservation row count unchanged when the outbox insert fails mid-prepare, and the retry runs as a first attempt" do
    company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "employee")
    entry = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: reservation_routes)
    body = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "disposition" => "active", "entries" => [entry] }
    before = reservation_row_counts

    allow(OutboxSnapshot).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "outbox down")
    failed = begin
      reservation_post("prepare", company:, credential: service, body:)
    rescue ActiveRecord::StatementInvalid
      nil
    end

    expect(failed&.status).not_to eq(200)
    expect(reservation_row_counts).to eq(before)
    expect(timekeeping_arrange.entry_locked(entry)).to be(false)

    allow(OutboxSnapshot).to receive(:insert_all!).and_call_original
    retried = reservation_post("prepare", company:, credential: service, body:)

    expect([retried.status, retried.parsed_body.fetch("state")]).to eq([200, "prepared"])
    expect(OutboxSnapshot.where(id: entry).count).to eq(1)
  end
end
